import{_ as s,o as e,c as n,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"60. Practice: Write Your Own Makefile","description":"The Little Book of C — 60. Practice: Write Your Own Makefile","frontmatter":{"title":"60. Practice: Write Your Own Makefile","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Compilation and Build]","description":"The Little Book of C — 60. Practice: Write Your Own Makefile","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"60","sidebarWeight":"60","lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/060-Practice Write Your Own Makefile","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/060-Practice Write Your Own Makefile"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/060-Practice Write Your Own Makefile.md","filePath":"posts/c教程/en-US/06-Compilation and Build/060-Practice Write Your Own Makefile.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/06-Compilation and Build/060-Practice Write Your Own Makefile.md"};function l(t,a,o,c,d,r){return e(),n("div",null,[...a[0]||(a[0]=[p(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/060-Practice Write Your Own Makefile)</p><h4 id="follow-along-deliverable" tabindex="-1">Follow-Along Deliverable <a class="header-anchor" href="#follow-along-deliverable" aria-label="Permalink to &quot;Follow-Along Deliverable&quot;">​</a></h4><ul><li>Assumed state: lessons 051-059 are complete and you can rebuild the previous example.</li><li>Working directory: <code>~/c-course-labs/060-makefile-lab</code>.</li><li>First command: on macOS / Linux run <code>mkdir -p ~/c-course-labs/060-makefile-lab &amp;&amp; cd ~/c-course-labs/060-makefile-lab</code>; on Windows PowerShell run <code>New-Item -ItemType Directory -Force &quot;$HOME\\c-course-labs\\060-makefile-lab&quot;; Set-Location &quot;$HOME\\c-course-labs\\060-makefile-lab&quot;</code>.</li><li>Success evidence: keep the source file, executable, <code>evidence.md</code>, and record <code>make</code>, one incremental rebuild after editing a <code>.c</code> file, and <code>make clean</code> output.</li><li>Boundary for this lab: This lab focuses on repeatable builds. CMake, Ninja, and release pipelines are out of scope.</li><li>Reset: remove the executable, temporary data, and generated output for this lab; keep source and <code>evidence.md</code> for review.</li></ul><p>Now that you understand how the C build process works, preprocessing, compiling, linking, and libraries, it’s time to tie everything together with your own Makefile.</p><p><code>make</code> is one of the oldest and most powerful automation tools in C development. It watches file timestamps, builds only what has changed, and lets you define build rules in a concise way.</p><p>By writing your own Makefile, you’ll automate your entire compilation workflow like a professional.</p><h4 id="step-1-create-the-project" tabindex="-1">Step 1. Create the Project <a class="header-anchor" href="#step-1-create-the-project" aria-label="Permalink to &quot;Step 1. Create the Project&quot;">​</a></h4><p>Let’s build a small multi-file project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>├── Makefile</span></span>
<span class="line"><span>├── main.c</span></span>
<span class="line"><span>├── math.c</span></span>
<span class="line"><span>├── math.h</span></span>
<span class="line"><span>└── string_utils.c</span></span></code></pre></div><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;2 + 3 = %d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>    printf(&quot;2 * 3 = %d\\n&quot;, mul(2, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span></code></pre></div><p>math.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_H</span></span>
<span class="line"><span>#define MATH_H</span></span>
<span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int mul(int a, int b);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><h4 id="step-2-write-the-simplest-makefile" tabindex="-1">Step 2. Write the Simplest Makefile <a class="header-anchor" href="#step-2-write-the-simplest-makefile" aria-label="Permalink to &quot;Step 2. Write the Simplest Makefile&quot;">​</a></h4><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main: main.c math.c</span></span>
<span class="line"><span>    gcc main.c math.c -o main</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./main</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 + 3 = 5</span></span>
<span class="line"><span>2 * 3 = 6</span></span></code></pre></div><p>This works, but<code>make</code> will rebuild everything every time, even if only one file changed.</p><p>Let’s make it smarter.</p><h4 id="step-3-split-the-compilation-steps" tabindex="-1">Step 3. Split the Compilation Steps <a class="header-anchor" href="#step-3-split-the-compilation-steps" aria-label="Permalink to &quot;Step 3. Split the Compilation Steps&quot;">​</a></h4><p>Separate compilation into object files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>main: main.o math.o</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) main.o math.o -o main</span></span>
<span class="line"><span>main.o: main.c math.h</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c main.c</span></span>
<span class="line"><span>math.o: math.c math.h</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c math.c</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f *.o main</span></span></code></pre></div><p>Now when you run<code>make</code>, it builds<code>.o</code> files only once, and recompiles only what changed.</p><p>Test it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>touch math.c</span></span>
<span class="line"><span>make</span></span></code></pre></div><p>You’ll see that only<code>math.o</code> is rebuilt.</p><h4 id="step-4-add-automatic-dependency-handling" tabindex="-1">Step 4. Add Automatic Dependency Handling <a class="header-anchor" href="#step-4-add-automatic-dependency-handling" aria-label="Permalink to &quot;Step 4. Add Automatic Dependency Handling&quot;">​</a></h4><p>Use pattern rules to avoid repeating commands for every<code>.c</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>OBJS = main.o math.o string_utils.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJS)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJS) -o $(TARGET)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJS) $(TARGET)</span></span></code></pre></div><p><code>$&lt;</code> means “the first dependency” (like<code>main.c</code>).<code>$@</code> means “the target” (like<code>main.o</code>).</p><p>Now the Makefile works for any<code>.c</code> file automatically.</p><h4 id="step-5-add-debug-and-release-targets" tabindex="-1">Step 5. Add Debug and Release Targets <a class="header-anchor" href="#step-5-add-debug-and-release-targets" aria-label="Permalink to &quot;Step 5. Add Debug and Release Targets&quot;">​</a></h4><p>Real projects have multiple build modes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>DEBUG_FLAGS = -g -O0 -DDEBUG</span></span>
<span class="line"><span>RELEASE_FLAGS = -O2 -DNDEBUG</span></span>
<span class="line"><span>OBJS = main.o math.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>.PHONY: all clean debug release</span></span>
<span class="line"><span>all: release</span></span>
<span class="line"><span>debug: CFLAGS += $(DEBUG_FLAGS)</span></span>
<span class="line"><span>debug: $(TARGET)</span></span>
<span class="line"><span>release: CFLAGS += $(RELEASE_FLAGS)</span></span>
<span class="line"><span>release: $(TARGET)</span></span>
<span class="line"><span>$(TARGET): $(OBJS)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJS) -o $(TARGET)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJS) $(TARGET)</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make debug</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>Then:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean</span></span>
<span class="line"><span>make release</span></span></code></pre></div><p>The debug build has symbols for<code>gdb</code>; the release build is optimized.</p><h4 id="step-6-add-static-and-shared-library-targets" tabindex="-1">Step 6. Add Static and Shared Library Targets <a class="header-anchor" href="#step-6-add-static-and-shared-library-targets" aria-label="Permalink to &quot;Step 6. Add Static and Shared Library Targets&quot;">​</a></h4><p>Add these to your Makefile:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.a: math.o</span></span>
<span class="line"><span>    ar rcs libmylib.a math.o</span></span>
<span class="line"><span>libmylib.so: math.o</span></span>
<span class="line"><span>    $(CC) -shared -o libmylib.so math.o</span></span></code></pre></div><p>Now you can build a reusable library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make libmylib.a</span></span>
<span class="line"><span>make libmylib.so</span></span></code></pre></div><h4 id="step-7-add-installation-and-help" tabindex="-1">Step 7. Add Installation and Help <a class="header-anchor" href="#step-7-add-installation-and-help" aria-label="Permalink to &quot;Step 7. Add Installation and Help&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>install:</span></span>
<span class="line"><span>    cp app /usr/local/bin/</span></span>
<span class="line"><span>help:</span></span>
<span class="line"><span>    @echo &quot;make [target]&quot;</span></span>
<span class="line"><span>    @echo &quot;Targets: all, debug, release, clean, install, libmylib.a, libmylib.so&quot;</span></span></code></pre></div><p>The<code>@</code> suppresses command echoing, only prints your messages.</p><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make help</span></span></code></pre></div><h4 id="step-8-use-variables-for-paths-and-options" tabindex="-1">Step 8. Use Variables for Paths and Options <a class="header-anchor" href="#step-8-use-variables-for-paths-and-options" aria-label="Permalink to &quot;Step 8. Use Variables for Paths and Options&quot;">​</a></h4><p>Clean up your Makefile by grouping related flags:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>SRC = $(wildcard *.c)</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>CFLAGS = -Wall -Wextra -std=c99</span></span>
<span class="line"><span>LDFLAGS = -lm</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJ) -o $(TARGET) $(LDFLAGS)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p><code>wildcard</code> and<code>patsubst</code> let you automatically include new<code>.c</code> files as the project grows.</p><h4 id="tiny-code-final-polished-makefile" tabindex="-1">Tiny Code: Final Polished Makefile <a class="header-anchor" href="#tiny-code-final-polished-makefile" aria-label="Permalink to &quot;Tiny Code: Final Polished Makefile&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -Wextra -std=c99 -O2</span></span>
<span class="line"><span>LDFLAGS = -lm</span></span>
<span class="line"><span>SRC = $(wildcard *.c)</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>all: $(TARGET)</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJ) -o $(TARGET) $(LDFLAGS)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>This pattern is simple, robust, and scalable, the foundation of nearly all C build systems.</p><h4 id="step-9-makefile-debugging" tabindex="-1">Step 9. Makefile Debugging <a class="header-anchor" href="#step-9-makefile-debugging" aria-label="Permalink to &quot;Step 9. Makefile Debugging&quot;">​</a></h4><p>To see what commands<code>make</code> is running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make VERBOSE=1</span></span></code></pre></div><p>Or trace variable expansions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -p</span></span></code></pre></div><p>Add<code>@echo &quot;Building $@&quot;</code> before commands for clarity.</p><h4 id="step-10-why-it-matters" tabindex="-1">Step 10. Why It Matters <a class="header-anchor" href="#step-10-why-it-matters" aria-label="Permalink to &quot;Step 10. Why It Matters&quot;">​</a></h4><p>A well-crafted Makefile:</p><ul><li>Automates your entire C build workflow</li><li>Avoids recompiling unchanged files</li><li>Scales to large multi-directory projects</li><li>Makes your builds reproducible across systems</li></ul><p>It’s your first step toward professional build systems like CMake, Meson, or Bazel, all of which build on these principles.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Add a new<code>.c</code> file and watch your Makefile compile it automatically.</li><li>Add a<code>test</code> target that compiles and runs unit tests.</li><li>Add colorized output using<code>tput</code> or ANSI escapes.</li><li>Build both static and shared libraries in one run.</li><li>Convert your Makefile to use multiple directories (<code>src/</code>,<code>include/</code>,<code>build/</code>).</li></ol><p>Congratulations! You’ve completed Chapter 6 – Compilation and the Build Process. You now understand how source becomes an executable, every stage from preprocessor to linker, and every tool in between.</p><p>Next, we’ll step deeper into Chapter 7: Working Close to the System, where your programs start interacting directly with the operating system through system calls, processes, and files.</p>`,77)])])}const m=s(i,[["render",l]]);export{u as __pageData,m as default};
